import unittest
class TestTranspose(unittest.TestCase):
    def test_run(self):
        m = [[1, 2], [3, 4]]
        transpose(m)
        self.assertEqual(m, [[1, 3], [2, 4]], 'Should transpose | Debería transponer | Irauli beharko luke')
